#!/usr/bin/env node
/**
 * Derive per-tool wire-schema sizes from the generated tool catalog.
 *
 * `docs/tool-catalog.md` is generated by booting every shipped tool plugin and
 * reading `ctx.tools.schemas()`, so it carries the same `name`, `description`
 * and `parameters` the model receives. This script rebuilds the wire object
 * `{ name, description, parameters }` per tool and measures it, which lets a
 * preset's surface be priced for tools that were never mounted in a captured
 * session. Validate it with `--verify <tool-bytes.json>` against a measured
 * request header before trusting its numbers.
 *
 * Usage:
 *   node bench/scripts/catalog-bytes.mjs --catalog <checkout>/docs/tool-catalog.md \
 *        [--verify bench/baselines/tool-bytes.json] [--out bench/baselines/catalog-bytes.json]
 */
import { readFileSync, writeFileSync } from 'node:fs'
import process from 'node:process'

const args = process.argv.slice(2)
const flag = name => {
  const index = args.indexOf(name)
  return index === -1 ? undefined : args[index + 1]
}
const catalogPath = flag('--catalog')
if (catalogPath === undefined) {
  process.stderr.write('usage: catalog-bytes.mjs --catalog <path/to/tool-catalog.md>\n')
  process.exit(2)
}

const markdown = readFileSync(catalogPath, 'utf8')
const lines = markdown.split('\n')

/** @type {Map<string, {bytes: number, description: string, parameterBytes: number}>} */
const tools = new Map()
let current = null
let buffer = []
let fence = null

/** Wire description: catalog paragraphs joined by a single space, matching the shipped strings. */
const joinDescription = paragraphs => paragraphs.join(' ').replace(/\s+/gu, ' ').trim()

for (const line of lines) {
  const heading = /^### `([^`]+)`$/u.exec(line)
  if (heading !== null) {
    if (current !== null) tools.set(current.name, finish())
    current = { name: heading[1], paragraphs: [] }
    buffer = []
    fence = null
    continue
  }
  if (current === null) continue
  if (line.startsWith('```')) {
    if (fence === null) {
      fence = 'json'
      continue
    }
    if (fence === 'json') {
      current.schemaText = buffer.join('\n')
      fence = 'done'
      continue
    }
  }
  if (fence === 'json') buffer.push(line)
  else if (fence === null && line.trim() !== '' && !line.startsWith('Source:')) current.paragraphs.push(line.trim())
}

/** Build the wire object and measure it. */
function finish() {
  const description = joinDescription(current.paragraphs)
  const parameters = JSON.parse(current.schemaText)
  const wire = { name: current.name, description, parameters }
  return {
    bytes: JSON.stringify(wire).length,
    descriptionChars: description.length,
    parameterBytes: JSON.stringify(parameters).length,
  }
}
if (current !== null) tools.set(current.name, finish())

const verifyPath = flag('--verify')
const summary = { toolCount: tools.size, catalog: catalogPath }
if (verifyPath !== undefined) {
  const measured = JSON.parse(readFileSync(verifyPath, 'utf8'))
  const deltas = []
  for (const [name, value] of Object.entries(measured.tools)) {
    const derived = tools.get(name)
    if (derived === undefined) {
      deltas.push({ name, measured: value.bytes, derived: null })
      continue
    }
    deltas.push({ name, measured: value.bytes, derived: derived.bytes, delta: derived.bytes - value.bytes })
  }
  const matched = deltas.filter(entry => entry.delta === 0).length
  const maxAbs = Math.max(...deltas.map(entry => Math.abs(entry.delta ?? 0)))
  summary.verify = {
    measuredTools: Object.keys(measured.tools).length,
    exactMatches: matched,
    maxAbsDelta: maxAbs,
    worst: deltas.filter(entry => Math.abs(entry.delta ?? 0) > 0).sort(
      (left, right) => Math.abs(right.delta ?? 0) - Math.abs(left.delta ?? 0),
    ).slice(0, 5),
  }
}

const out = {
  ...summary,
  tools: Object.fromEntries([...tools.entries()].sort(([left], [right]) => left.localeCompare(right))),
}
const outPath = flag('--out')
if (outPath !== undefined) writeFileSync(outPath, `${JSON.stringify(out, null, 1)}\n`)
process.stdout.write(`${JSON.stringify(summary, null, 1)}\n`)
